DO $$
BEGIN
  IF (SELECT tope_encargo_usd FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') IS DISTINCT FROM 58::numeric THEN
    RAISE EXCEPTION '202611171900 REVERSA: el video no quedó en 58';
  END IF;
  IF (SELECT count(*) FROM pg_constraint WHERE conname IN ('oficina_encargos_tope_valido', 'oficina_tipos_tope_valido') AND pg_get_constraintdef(oid) LIKE '%<= (60)%') IS DISTINCT FROM 2 THEN
    RAISE EXCEPTION '202611171900 REVERSA: las dos reglas no quedaron en 60';
  END IF;
  IF (SELECT valor FROM public.cadena_config WHERE clave = 'brazo_de_video') IS DISTINCT FROM $brazo${"tope_por_video_usd":15}$brazo$::jsonb THEN
    RAISE EXCEPTION '202611171900 REVERSA: el brazo no volvió a 15';
  END IF;
END $$;

